function lzwCompress(str){
  var dict={}, dictSize=256;
  for(var i=0;i<256;i++) dict[String.fromCharCode(i)]=i;
  var w='';
  var codes=[];
  for(var i=0;i<str.length;i++){
    var c=str.charAt(i);
    var wc=w+c;
    if(dict[wc]!==undefined){ w=wc; }
    else { codes.push(dict[w]); if(dictSize<65536) dict[wc]=dictSize++; w=c; }
  }
  if(w!=='') codes.push(dict[w]);
  return codes;
}
function lzwDecompress(codes){
  if(!codes.length) return '';
  var dict={}, dictSize=256;
  for(var i=0;i<256;i++) dict[i]=String.fromCharCode(i);
  if(dict[codes[0]]===undefined) throw new Error('bad code '+codes[0]);
  var w=dict[codes[0]];
  var result=w;
  for(var i=1;i<codes.length;i++){
    var k=codes[i];
    var entry;
    if(dict[k]!==undefined) entry=dict[k];
    else if(k===dictSize) entry=w+w.charAt(0);
    else throw new Error('bad code '+k);
    result+=entry;
    if(dictSize<65536) dict[dictSize++]=w+entry.charAt(0);
    w=entry;
  }
  return result;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { lzwCompress:lzwCompress, lzwDecompress:lzwDecompress };
}
if (typeof window !== 'undefined') {
  window.LzwForgePure = { lzwCompress:lzwCompress, lzwDecompress:lzwDecompress };
}
